import React, { useState } from 'react';
import ResourceCard from '../components/ResourceCard'

const resources = [
    {
        title: "Post-Harvest Handling Guide",
        type: "PDF",
        source: "Kenya Agri Institute",
        link: "#"
    },
    {
        title: "Organic Avocado Farming",
        type: "Video",
        source: "AgriTube",
        link: "#"
    },
    {
        title: "GlobalGAP Certification Steps",
        type: "Article",
        source: "ESH Export Board",
        link: "#"
    },
];

const KnowledgeHubPage = () => {
    const [query, setQuery] = useState('');
    const filteredResources = resources.filter(r =>
        r.title.toLowerCase().includes(query.toLowerCase())
    );

    return (
        <div className="container mx-auto px-4 py-8">
            <div className="text-center mb-10">
                <h1 className="text-3xl font-bold text--900 dark:text-white">Knowledge Hub</h1>
                <p className="text-gray-600 dark:text-gray-300 mt-2">
                    Educational guides, best practices, and certification resources for producers
                </p>
                <input
                    type="text"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="Search resources..."
                    className="mt-4 px-4 py-2 w-full max-w-md rounded-md border border-gray-300 focus:outline-none focus:ring-2 focus:ring-teal-500"
                />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredResources.map((res, index) => (
                    <ResourceCard key={index} {...res} />
                ))}
            </div>
        </div>
    );
};

export default KnowledgeHubPage;
